+++ b/libpod/container_dependency_health.go
@@ -0,0 +1,67 @@
+//go:build !remote
+
+package libpod
+
+import (
+	"context"
+	"fmt"
+
+	"go.podman.io/podman/v6/libpod/define"
+)
+
+const healthyDependenciesLabel = "io.podman.compose.requires-healthy.v1"
+
+// waitForHealthyDependencies gates startup on optional Compose metadata without
+// changing the dependency graph. The caller holds c's lock; dependency locks are
+// acquired only by the existing state/health accessors, never across a wait.
+func (c *Container) waitForHealthyDependencies(ctx context.Context) error {
+	raw, present := c.config.Labels[healthyDependenciesLabel]
+	if !present {
+		return nil
+	}
+	var names []string
+	if err := json.Unmarshal([]byte(raw), &names); err != nil {
+		return fmt.Errorf("container %s: invalid %s: %w", c.ID(), healthyDependenciesLabel, err)
+	}
+	if names == nil {
+		return fmt.Errorf("container %s: %s must be a JSON array of container names", c.ID(), healthyDependenciesLabel)
+	}
+	if len(names) == 0 {
+		return nil
+	}
+
+	// Resolve names only within the existing ID-based dependency graph. A rename
+	// must fail closed instead of following a different container with that name.
+	dependencies := make(map[string]*Container)
+	for _, id := range c.Dependencies() {
+		dep, err := c.runtime.state.Container(id)
+		if err != nil {
+			return fmt.Errorf("retrieving dependency %s of container %s: %w", id, c.ID(), err)
+		}
+		dependencies[dep.Name()] = dep
+	}
+	for _, name := range names {
+		dep, found := dependencies[name]
+		if !found {
+			return fmt.Errorf("container %s: healthy dependency %q is not an existing dependency", c.ID(), name)
+		}
+		if !dep.HasHealthCheck() {
+			return fmt.Errorf("container %s: healthy dependency %q has no healthcheck", c.ID(), name)
+		}
+	}
+	for _, name := range names {
+		dep := dependencies[name]
+		if _, err := dep.WaitForConditionWithInterval(ctx, DefaultWaitInterval, define.HealthCheckHealthy); err != nil {
+			return fmt.Errorf("container %s: waiting for healthy dependency %q: %w", c.ID(), name, err)
+		}
+		// The generic health wait can observe a final healthy result after exit.
+		state, err := dep.State()
+		if err != nil {
+			return fmt.Errorf("container %s: checking healthy dependency %q: %w", c.ID(), name, err)
+		}
+		if state != define.ContainerStateRunning {
+			return fmt.Errorf("container %s: healthy dependency %q is not running: %w", c.ID(), name, define.ErrCtrStateInvalid)
+		}
+	}
+	return nil
+}
