@@ -0,0 +1,38 @@
+//go:build !remote
+
+package libpod
+
+import (
+	"context"
+	"strings"
+	"testing"
+)
+
+func TestHealthyDependencyMetadata(t *testing.T) {
+	for _, test := range []struct {
+		name   string
+		labels map[string]string
+		err    string
+	}{
+		{name: "legacy"},
+		{name: "empty array", labels: map[string]string{healthyDependenciesLabel: "[]"}},
+		{name: "empty value", labels: map[string]string{healthyDependenciesLabel: ""}, err: "invalid"},
+		{name: "null", labels: map[string]string{healthyDependenciesLabel: "null"}, err: "JSON array"},
+		{name: "object", labels: map[string]string{healthyDependenciesLabel: "{}"}, err: "invalid"},
+		{name: "number", labels: map[string]string{healthyDependenciesLabel: "[1]"}, err: "invalid"},
+		{name: "extra dependency", labels: map[string]string{healthyDependenciesLabel: `["db"]`}, err: "not an existing dependency"},
+	} {
+		t.Run(test.name, func(t *testing.T) {
+			ctr := &Container{config: &ContainerConfig{}}
+			ctr.config.Labels = test.labels
+			err := ctr.waitForHealthyDependencies(context.Background())
+			if test.err == "" {
+				if err != nil {
+					t.Fatal(err)
+				}
+			} else if err == nil || !strings.Contains(err.Error(), test.err) {
+				t.Fatalf("expected error containing %q, got %v", test.err, err)
+			}
+		})
+	}
+}
