@@ -0,0 +1,45 @@
+import json
+import unittest
+from unittest import mock
+
+from podman_compose import ServiceDependency, container_to_args
+
+
+class TestHealthyDependencyMetadata(unittest.IsolatedAsyncioTestCase):
+    async def args(self, dependencies, no_deps=False):
+        compose = mock.Mock()
+        compose.dirname = "/tmp"
+        compose.default_net = None
+        compose.networks = {}
+        compose.x_podman = {}
+        compose.container_names_by_service = {
+            "db": ["project_db_2", "project_db_1"],
+            "cache": ["project_cache_1"],
+        }
+        cnt = {
+            "name": "project_app_1", "service_name": "app", "image": "busybox",
+            "depends_on": dependencies,
+            "_deps": {ServiceDependency("db", "service_healthy"),
+                      ServiceDependency("cache", "service_started")},
+        }
+        return await container_to_args(compose, cnt, no_deps=no_deps)
+
+    async def test_direct_scaled_health_dependency(self):
+        args = await self.args({"db": {"condition": "service_healthy"}})
+        label = next(a for a in args if a.startswith("io.podman.compose.requires-healthy.v1="))
+        self.assertEqual(json.loads(label.split("=", 1)[1]), ["project_db_1", "project_db_2"])
+        requires = next(a for a in args if a.startswith("--requires="))
+        self.assertEqual(set(requires.split("=", 1)[1].split(",")),
+                         {"project_db_1", "project_db_2", "project_cache_1"})
+
+    async def test_transitive_health_not_promoted(self):
+        args = await self.args({"cache": {"condition": "service_started"}})
+        self.assertFalse(any("requires-healthy" in a for a in args))
+
+    async def test_no_deps(self):
+        args = await self.args({"db": {"condition": "service_healthy"}}, no_deps=True)
+        self.assertFalse(any("requires" in a for a in args))
+
+    async def test_started_only(self):
+        args = await self.args({"db": {"condition": "service_started"}})
+        self.assertFalse(any("requires-healthy" in a for a in args))
